var seed = Math.random() * 15283;
var t;
var num, vNum;
var radius, mySize, margin;
var sizes = [];

let color_bg;
let v_planet = [];

function setup() {
	randomSeed(seed);
	// pixelDensity(5);
	mySize = max(windowWidth, windowHeight);
	margin = mySize / 100;
	createCanvas(windowWidth, windowHeight, WEBGL);

	color_bg = "#202020";
	background(color_bg);
	// num = 50;
	num = int(random(30, 10));
	radius = mySize * 0.75;
	for (let a = 0; a < TAU; a += TAU / num) {
		sizes.push(random(0.1, 0.5))
	}
	t = 0;
}

function draw() {
	randomSeed(seed);
	background(color_bg);

	for (let i = 0; i < num; i++) {
		let a = (TAU / num) * i;
		let x = radius * sin(a + t) / random(5, 3) / 1.0;
		let y = radius * cos(a + t) / random(3, 5) / 1.0;
		v_planet[i] = createVector(x + 10, y + 10); //makes vector the boxes move along?
	}
	push();

	for (let q = 0; q < 1 / 5; q += 2 * random(0.01, 0.02)) {
		for (let j = 0; j < 1; j++) {
			let n = noise(q*t, j*t,frameCount*0.01); //?


			for (let i = 0; i < num; i += 4) {
				let d = (1.5 + sin(t)) * random(radius / 2, radius / 4);
				let x_plus = 0.5 * random(-d, d) / 1;
				let y_plus = 0.5 * random(-d, d) / 1;
				let z_plus = 0.5 * random(-d, d) / 1;
				stroke(random(255), random(255), random(255)); //random stroke color
				strokeWeight(random(0.5, 2)); //thicker strokes

				fill(random(255), random(255), random(255));//random box colors

				push();
				translate(v_planet[i].x + x_plus + random(50), v_planet[i].y + y_plus + random(50), z_plus + random(20));// increase range the squares move
				rotateX(random(TAU)+t);
				rotateY(random(-TAU)+t); 
				rotateZ(random(PI)+t);
				box(random(80)); //draws a bunch of boxes with increases size range
				pop();
			}
		}
	}
	pop();

	t += random(2, 1) * random(0.001, 0.005) / 1;
}


function keyTyped() {
	if (key === "s" || key === "S") {
		num = random(50, 100);
		//saveCanvas("0712_Emotional lines_12_2022", "png");
	} else if (key === "d" || key === "D") {
		num = random(5, 10);
	} else if (key === "w" || key === "W") {
		num = random(40, 60);
	} else if (key === "a" || key === "A") { // click a, s, w, or d and change the amount of boxes
		num = random(10, 30);
	}
}

